		t.Fatalf("mattermost.server_url = %q, want https://mm.example.com", mm.ServerURL)
	}
	if mm.Token != "mattermost-bot-token" {
		t.Fatalf("mattermost.token = %q, want mattermost-bot-token", mm.Token)
	}
