		t.Fatalf("mattermost.bot_user_id = %q, want bot-user-id", mm.BotUserID)
	}
	if err := validateBaldaApplication(prepared); err != nil {
		t.Fatalf("validateBaldaApplication with Mattermost transport: %v", err)
	}
}

